const digits='٠١٢٣٤٥٦٧٨٩';
const norm=(value)=>String(value||'')
  .normalize('NFKC')
  .replace(/[\u064B-\u065F\u0670\u06D6-\u06ED]/g,'')
  .replace(/[أإآٱ]/g,'ا').replace(/ى/g,'ي').replace(/ة/g,'ه').replace(/ؤ/g,'و').replace(/ئ/g,'ي')
  .replace(/[٠-٩]/g,d=>String(digits.indexOf(d)))
  .toLowerCase().replace(/[^a-z0-9\u0600-\u06ff]+/g,' ').trim().replace(/\s+/g,' ');
const compact=(value)=>norm(value).replace(/\s+/g,'');
const grams=(value,n=3)=>{const s=compact(value);const out=new Set();if(s.length<n){if(s)out.add(s);return out;}for(let i=0;i<=s.length-n;i++)out.add(s.slice(i,i+n));return out;};
const dice=(a,b)=>{const A=grams(a),B=grams(b);if(!A.size||!B.size)return 0;let hit=0;for(const g of A)if(B.has(g))hit++;return 2*hit/(A.size+B.size);};
const tokens=(value)=>new Set(norm(value).split(' ').filter(Boolean));
const jaccard=(a,b)=>{const A=tokens(a),B=tokens(b);if(!A.size||!B.size)return 0;let hit=0;for(const t of A)if(B.has(t))hit++;return hit/(A.size+B.size-hit);};
const isNear=(a,b)=>{const ac=compact(a),bc=compact(b);if(!ac||!bc)return false;if(ac===bc)return true;const ratio=Math.min(ac.length,bc.length)/Math.max(ac.length,bc.length);if(ratio<0.72)return false;return dice(a,b)>=0.88 || (jaccard(a,b)>=0.82 && dice(a,b)>=0.78);};

const existing=[];
for(const value of Object.values(window)){
  if(!Array.isArray(value))continue;
  for(const item of value){
    if(item&&typeof item==='object'&&Array.isArray(item.options)&&(item.q||item.question)) existing.push(item.q||item.question);
  }
}
const accepted=[];
for(const [id,sourceTimestamp,category,level,q,options,answer,explain] of rows){
  if(existing.some(old=>isNear(q,old))) continue;
  if(accepted.some(item=>isNear(q,item.q))) continue;
  const item={id:`monsef007-20260809-${id}`,area:'exams',family:'qudurat',subject:'qudurat-quant',category,level,q,options,answer,explain,source,sourceTimestamp};
  accepted.push(item); existing.push(q);
}
window.NEON_UPLOADED_MONSEF007_QUANT_20260809=accepted;
window.NEON_UPLOADED_MONSEF007_QUANT_20260809_META={source,candidates:rows.length,accepted:accepted.length,duplicatesSkipped:rows.length-accepted.length};
